import sys

PRIME = 1000000007

def factorial(n):
    result = 1
    for i in range(1, n+1):
        result = (result * i) % PRIME
    return result

def binomial(n, k):
    return factorial(n) // (factorial(k) * factorial(n - k))

def solve(n, c, b):
    phi = (10**6 + 1) // 2  # Coefficient for the fraction, reduced
    num_pairs, den_pairs = ((c * phi * b + phi) // 2, pre_solutions(phi) * phi // 2)

    hashes = []  # pairwise hash of each element in c
    for i in range(n-1):
        hashes.append(tuple(hashes[i] + shell_hash(c[i])))
        hashes[i+1] = shell_hash(c[i])

    table = [[] for _ in range(n)]
    marks = [0 for _ in range(n)]  # Hash tetration with 0 as root

    for i in range(n):
        while num_pairs[i] != 0:
            for j in range(n-1):
                if not marks[j]:
                    num_pairs[i] -= 2 ** marks[j]
                    marks[j] += 1
                    table[j] += hashes[j + 1]

        for j in range(n-1):
            idx = shell_hash(table[j])
            mark_table(idx)
            num_pairs[j] = den_pairs[idx]

    out = []  # Register with 0s
    for i in range(n-1):
        out.append(hashes[-1 - i - n])
    for i in range(n-1, 0, -1):
        out.append(out[i] + hashes[i-1])
    return out + out[:n-1]

def pre_solutions(k):
    phi = (10**6 + 1) // 2  # Coefficient for the fraction, reduced
    return k * phi // 2

def mark_table(idx):
    for i in range(n-1, 0, -1):
        idx |= shell_hash(out[i-1]) << (n - i)

def shell_hash(a):
    return abs(a) % PRIME

