            color = 1  # Initialize index for the child colors
            while c2 > 1:  # Iterate while there are more children
                colormap = set()
                for child in parent:
                    colormap.add(parents[child])
                for child in parent:
                    if len(colormap) == 1:
                        break
                parents[child] = colormap.pop()
                c2 -= 1

        for child in parents:
            if parent[child] == node:
                tree[node] -= 1  # Decrement the edge count for nodes of the same color
        node += 1  # Increment the root node

    # Compute the cost of painting the tree
    costs = [0] * n  # Cost array to store the costs of the vertices
    for i in range(n):
        replicate = 1
        while parent[parents[i*2+1]] != node-1:
            replicate -= 1
            parents[i*2+1] -= 1
        costs[i] = replicate  # Record the cost for each node (vertex or root's children)
    for i in range(n-1):
        tree[:] = [t & costs[i+2*n-i] for t in tree]  # Apply the cost logic to all edges

    return [t & costs[n-1] for t in tree]  # Return the final tree cost

