def build_tree(n):
    # Build multi-target tree structure
    nodes = [TreeNode(1)]
    for i in range(1, n):
        parent = i + 1
        child = nodes[i]
        nodes.append(child)
        nodes.append(TreeNode(parent + 1))
        child.children[nodes[i + 1]] = nodes[nodes[i] + 1]
    return nodes[0]

def calculate_costs(tree):
