from math import gcd
from itertools import product

MOD = 1000000007

def count_solutions(m, mod):
    if not m: 
        return [1] or [0]

    sm = sum([a for a, b in product(range(2, mod + 1), repeat=m) if gcd_count(b, mod) == m])

    if m == 1:
        return sm % mod

    p = m - 1
    q = MOD + (MOD - 1) * (MOD - 3) // 4
    return sm * q % MOD  // p

def gcd_count(a, mod):
    if not a: 
        return 0

    d = 1
    for i in range(2, min(a, mod // 2) + 1):
        if a % i:
            continue
        l = 1
        div = a // i

        while div % i == 0:
            l = l * i
            div //= i

        d = gcd(d, l)

    return d

