                            _heapq.heappush(new_group, -participant_count + i * 2 + 1)

                        total_people -= participant_count
                        break
            else:
                return None

    return [subgroup[0] for subgroup in subgroups]

def calculate_group(a, b, c, participants, h):
    queue = []

    if participants == 1:
        if a > 1 or b > 1:
            return -1
        elif c > 0:
            queue.append(1)
    elif participants == 2:
        if b > 1:
            queue.append(1)
        if c > 1:
            queue.append(1)
        if a > 1:
            queue.append(2)
        if (a >= b and b > 1) or (a + 1 >= b + 1 and b >= c) or (a + 2 >= b + 2 and b + c + 1 >= 3):
            queue.extend((h + 1) * [2])
        if (a >= c and (b + c) < (a + 1)):
            queue.append((h + 1) * [0])
            # participants == 2 | xor()\n
    return queue

