import sys

def ask_query(n, nodes):
    query_string = "?"

    if n == 2:
        query_string += f" {nodes[0]} {nodes[1]}"
        print(query_string, flush=True)
        return eval(input()).split()
    elif n == 3:
        first_indices = list(nodes[0] + 1)
        second_indices = list(nodes[1] + 1)
        third_indices = list(nodes[2] + 1)
        query_string += f" {first_indices[0]} {first_indices[1]}\n"
        for i in third_indices:
            query_string += f" {nodes[0]} {i}\n"  # Query f from c [1, 2]

        print(query_string, flush=True)
        return eval(input()).split()
    else:
        query_string += f" {n - 2} "

        for i in range(0, n):
            if i not in nodes:
                query_string += f"{i} "
        query_string = query_string[:-1]
        query_string += "?"

        print(query_string, flush=True)

        result = input().split()
        while result[0] not in nodes:
            for i in range(len(result) - 1):
                if result[i] != result[i+1]:
                    query_string = query_string[:result[i] + 1] + f" {result[i+1] - result[i] + 1}"
                    query_string += result[result[i] + 1:]
                    break
            if result[-1] != 2:
                query_string = query_string[:-1] + " " + result[-1]
                query_string = "?" + query_string + input().split()
                continue

            if len(result[0]) > 1:
                query_string = f" {result[0]}"
                query_string += query_string + "?"
                print(query_string, flush=True)
                return eval(input()).split()
            else:
                query_string = f" {result[0] + 1}"
                for query_node in range(1, len(nodes) - 1):
                    if nodes[query_node] != result[0]:
                        query_string += f" {result[0] + 1}"
                        break

                query_string += " "
                print(query_string, flush=True)

                query_result = input().split()
                if (-1 in [int(d) for d in query_result]) or int(d) not in query_result:
                    return ask_query(n - 3, nodes)
                else:
                    return query_result
