def min_operations_to_multiple_of_three(n, a):
    result = 0
    for i in range(n):
        if a[i] % 3 == 0:
            continue
        for j in range(i + 1, n):
            if a[j] % 3 == 0:
                continue
            diff = abs(a[i] - a[j]) % 3
            if diff == 2:
                a[i] = a[(i + j) // 2]
                a[j] = a[(i + j) // 2]
            elif diff == 1:
                a[i] = a[i] + a[j]
                a[j] = a[i]
            elif diff == 0:
                a[j] = a[i] - a[j]
                continue
        result += 1
    return result

