                total -= a1 * students
            if b1 * students <= total:
                students *= b1
                total -= b1 * students
            if c1 * students <= total:
                students *= c1
                total -= c1 * students

        if students != total:
            return -1

        rest = total
        students = 1
        while rest > 0:
            if rest >= c2 and total - a2 * students >= c2 * students - rest:
