        while total:
            students += 1
            if d6 * students <= total:
                total -= d6 * students
            elif d5 * students <= total:
                total -= d5 * students
            else:
                break

        if students != max(a2, b2, c2):
            return -1

        for i in range(7):
            subgroups[i][f'{a1}-{b1}-{c1}'].append(d[i])
            subgroups[i][f'{a2}-{b2}-{c2}'].append(d[i] * students)
            subgroups[i]['total'] += d[i] * students

    results = []
