from math import gcd, lcm, prod
from fractions import Fraction

def prime_factorization(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def totient(n):
    factors = prime_factorization(n)
    visible_factors = filter(lambda x: x == x, factors)
    powers = map(lambda x: len(prime_factorization(x)), visible_factors)
    numerator = prod(visible_factors)
    denominator = prod([x**power - x for x, power in zip(visible_factors, powers)])
    return fraction(numerator, denominator)

