def find_f_k(b, f_k, n, m):
    exponents = [b[i] * k for i, k in enumerate(b) if i <= n-1]
    if m not in exponents:
        return -1
    for i in range(1, n):
        if power(m, i, p) in exponents and (m - power(m, i, p)) // (product(exponents[:i])) >= 1:
            return i
    return -1

def power(x, n, p):
    result = 1
    x = x % p
    while n > 0:
        if n % 2:
            result = result * x % p
        x = x * x % p
        n //= 2
    return result % p

def product(exponents):
    result = 1
    for exponent in exponents:
        result = result * exponent % p
    return result % p

