from collections import defaultdict

def decinc_subsequences(p):
    q = defaultdict(list)
    stack = []

    for i, v in enumerate(p):
        while stack and p[stack[-1]] > v:
            stack.pop()
        if stack:
            q[i].append(stack[-1])
            q[stack[-1]].insert(0, i)
        stack.append(i)

    return q


def count_decinc_subarrays(p):
    n = len(p)
    q = decinc_subsequences(p)

    dp = [0] * (n + 1)
    for r in range(n + 1):
        dp[r] = dp[r - 1] if r > 0 else 1
        start = min(r + 1, n + 1)

        for l in range(1, r + 1):
            if q[l][: (r + 1 - l)] not in q[r]:
                dp[r] += dp[l - 1]

    return dp[-1] - 1


if __name__ == "__main__":
    n = int(input())
    p = list(map(int, input().split()))
    print(count_decinc_subarrays(p))
